import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: PlaneGeo, Color: ThreeColor } = ctx.THREE;

  // Root container
  const root = new ThreeGroup();
  root.name = 'FooterColophon';

  // =========================
  // Backdrop plane with gradient
  // =========================
  const width = 6.8;
  const height = 2.0;

  const backdropGeo = new PlaneGeo(width, height);
  // Gradient: vertical from #121218 (top) to #0b0b10 (bottom)
  const gradNode = mix(color('#121218'), color('#0b0b10'), uv().y);
  const backdropMat = new ctx.THREE.MeshStandardNodeMaterial();
  backdropMat.colorNode = gradNode;
  backdropMat.roughness = 0.6;
  backdropMat.metalness = 0.2;
  const backdropMesh = new ThreeMesh(backdropGeo, backdropMat);
  root.add(backdropMesh);

  // =========================
  // Top hairline rule
  // =========================
  const hairHeight = 0.006;
  const hairGeo = new PlaneGeo(width, hairHeight);
  const hairMat = new ctx.THREE.MeshBasicNodeMaterial();
  hairMat.color = new ThreeColor('#23232b');

  const topHair = new ThreeMesh(hairGeo, hairMat);
  topHair.position.y = height / 2 - hairHeight / 2; // top edge
  root.add(topHair);

  // =========================
  // Wordmark block (left side)
  // =========================
  const wordmarkGroup = new ThreeGroup();
  // Position the block: left edge starts at -width/2, block width 2.0, centre at -width/2 + 1.0
  wordmarkGroup.position.x = -width / 2 + 1.0;
  wordmarkGroup.position.y = 0.2; // slight upward offset

  const wordmarkText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    color: '#16161d',
    align: 'left',
    letterSpacing: 0.02,
    lineHeight: 1,
  });
  wordmarkText.position.set(0, 0, 0);
  wordmarkGroup.add(wordmarkText);

  // Accent bar beneath the wordmark
  const accentGeo = new PlaneGeo(0.3, 0.02);
  const accentMat = new ctx.THREE.MeshStandardNodeMaterial();
  accentMat.colorNode = color('#ff2a38');
  accentMat.emissiveNode = color('#ff2a38');
  accentMat.emissiveIntensity = 1.4;
  accentMat.roughness = 1.0;
  accentMat.metalness = 0.0;
  const accentBar = new ThreeMesh(accentGeo, accentMat);
  accentBar.position.set(0, -0.07, 0.001);
  wordmarkGroup.add(accentBar);

  root.add(wordmarkGroup);

  // =========================
  // Link columns
  // =========================
  const columnsData = [
    {
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
    },
    {
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
    },
    {
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
    },
  ];

  const colWidth = 1.2;
  const gutter = 0.375;

  // First column left edge after wordmark block
  const firstColLeft = -width / 2 + 2.0 + gutter;

  for (let i = 0; i < columnsData.length; i++) {
    const colInfo = columnsData[i];
    const colGroup = new ThreeGroup();

    const colCenterX = firstColLeft + i * (colWidth + gutter) + colWidth / 2;
    colGroup.position.x = colCenterX;

    // Header
    const headerObj = ctx.fontAtlas.createText(colInfo.header, {
      fontSize: 9,
      color: '#16161d',
      align: 'center',
      letterSpacing: 0.12,
      lineHeight: 1.2,
    });
    headerObj.position.set(0, 0.4, 0);
    colGroup.add(headerObj);

    // Links
    for (let j = 0; j < colInfo.links.length; j++) {
      const linkStr = colInfo.links[j];
      const linkObj = ctx.fontAtlas.createText(linkStr, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'center',
        lineHeight: 1.8,
      });

      const yPos = 0.4 - (j + 1) * 0.25; // baseline‑grid spacing
      linkObj.position.set(0, yPos, 0);

      // Interaction handlers (hover)
      const originalCol = new ThreeColor('#e8ecf2');
      const hoverCol = new ThreeColor('#ff2a38');
      let hoverTimeline = null;

      linkObj.userData.handlers = {
        hoverEnter: () => {
          if (hoverTimeline) hoverTimeline.kill();
          hoverTimeline = gsap.timeline();
          hoverTimeline.to(linkObj.material.color, {
            r: hoverCol.r,
            g: hoverCol.g,
            b: hoverCol.b,
            duration: 0.14,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          });
          hoverTimeline.to(
            linkObj.position,
            {
              z: 0.02,
              duration: 0.14,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            },
            0
          );
        },
        hoverLeave: () => {
          if (hoverTimeline) hoverTimeline.kill();
          hoverTimeline = gsap.timeline();
          hoverTimeline.to(linkObj.material.color, {
            r: originalCol.r,
            g: originalCol.g,
            b: originalCol.b,
            duration: 0.14,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          });
          hoverTimeline.to(
            linkObj.position,
            {
              z: 0,
              duration: 0.14,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            },
            0
          );
        },
      };

      colGroup.add(linkObj);
    }

    root.add(colGroup);
  }

  // =========================
  // Bottom hairline and legal line
  // =========================
  const bottomHair = new ThreeMesh(hairGeo.clone(), hairMat.clone());
  // Position: bottom edge + 0.25 clearance above the hairline, then hairline height
  bottomHair.position.y = -height / 2 + 0.25 + hairHeight / 2;
  root.add(bottomHair);

  const legalText = ctx.fontAtlas.createText(
    '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
    {
      fontSize: 9,
      color: '#16161d',
      align: 'center',
      letterSpacing: 0.04,
      lineHeight: 1.4,
    }
  );
  legalText.position.y = -height / 2 + 0.375; // 0.375 units above bottom edge as described
  root.add(legalText);

  // =========================
  // Fade‑up animation for the whole band
  // =========================
  gsap.from(root.position, {
    y: 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  gsap.from(root.scale, {
    x: 0.95,
    y: 0.95,
    z: 0.95,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  gsap.from(root, {
    opacity: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });

  // =========================
  // Cleanup
  // =========================
  root.userData.cleanup = () => {
    gsap.globalTimeline.clear();

    const disposeRecursively = (obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose && m.dispose());
        } else {
          obj.material.dispose && obj.material.dispose();
        }
      }
      if (obj.children) obj.children.forEach(disposeRecursively);
    };
    disposeRecursively(root);
  };

  return root;
}
